from durationkit import parse_duration
valid = {'90':90.0, '  42 ':42.0, '0':0.0, '00090':90.0, '2d':172800.0, '3h':10800.0, '15m':900.0, '45s':45.0, '500ms':0.5, '1h30m':5400.0, '2d4h':187200.0, '1m1s':61.0, '1s500ms':1.5, '1d1h1m1s1ms':90061.001, '1d1ms':86400.001, '1h1s':3601.0, ' 1h 30m ':5400.0, '\t1h\n30m\r':5400.0, '0s':0.0, '0ms':0.0, '0d0h0m0s0ms':0.0, '001h030m':5400.0, '90m':5400.0, '1500ms':1.5}
invalid = ['', '   ', '\t\n', '-1', '-1h', '+1', '+1h', '1.5', '1.5h', '.5s', '1e3s', '1_000s', '1,000s', '1x', '1H', '1MS', 'h', 'ms', '1hms', '1h1h', '1ms2ms', '0s0s', '30m1h', '1ms1s', '1s1d', '0m0h', '1h30', '1 30m', '1h,30m', 'abc', '1s500m', '1 h', '500 ms', '1h 30 m', '①', '①h', 'Ⅳ', 'Ⅳs', '½', '½h']
for value, expected in valid.items():
    actual = parse_duration(value)
    assert isinstance(actual, float) and abs(actual - expected) < 1e-9, (value, actual, expected)
for value in invalid:
    try: parse_duration(value)
    except ValueError: pass
    else: raise AssertionError(('accepted invalid', value))
for value in [90, 0.5, None, True, b'90', []]:
    try: parse_duration(value)
    except TypeError: pass
    else: raise AssertionError(('accepted non-string', value))
print(f'checked {len(valid)} valid, {len(invalid)} invalid, and 6 non-string cases')
